@font-face{font-family:'Builder Sans User';src:url(data:font/otf;base64,) format('opentype');font-weight:700;font-display:swap}
@font-face{font-family:'Builder Sans User';src:url(data:font/otf;base64,) format('opentype');font-weight:800;font-display:swap}

.home-nav-bottom .rbx-icon{font-size:27px}
.rbx-chat-panel{width:min(430px,calc(100vw - 32px));height:310px}
.rbx-chat-messages{font-size:15px;line-height:1.4}
.rbx-chat-tabs button{font-size:14px}
.rbx-chat-form input{font-size:15px}
.rbx-chat-form button{min-width:40px;min-height:38px}
.rbx-more-panel button{min-height:48px;font-size:15px}
.rbx-menu-dialog{font-size:15px}
@media(max-width:620px){.rbx-chat-panel{width:min(390px,calc(100vw - 24px));height:280px}}
@media (pointer:coarse){body.keyboard-open .rbx-backpack{ height:var(--visible-height); bottom:auto; }
body.keyboard-open .rbx-menu-overlay{ top:var(--visible-top,0px); height:var(--visible-height); bottom:auto; }
#rbx-backpack-search{ font-size:24px!important; }

body.keyboard-open .rbx-chat-panel{ max-height:calc(var(--visible-height) - 68px)!important; }
.rbx-character-modal{ top:var(--visible-top,0px); height:var(--visible-height,100%); bottom:auto; }
.rbx-menu-dialog{ max-height:calc(var(--visible-height,100dvh) - 24px)!important; }}
 .rbx-profile-actions button{ font: 700 12px Arial, Helvetica, sans-serif; color: #fff; background: #5a5d61; border: 0; border-radius: 4px; padding: 6px 10px; cursor: pointer; }
 .rbx-profile-actions button.primary{ background: #02b757; }
 .rbx-profile-actions button:hover:not(:disabled){ filter: brightness(1.12); }
.rbx-profile-actions{ display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 8px 0; }
.rbx-profile-actions button{ flex: 1 1 auto; }
.rbx-profile-actions button:disabled{ opacity: .6; cursor: default; }
.rbx-profile-actions .social-note{ font: 600 11px Arial, Helvetica, sans-serif; color: #bbb; }
.rbx-announce{ position: fixed; inset: 0; z-index: 90; display: grid; place-items: center; background: rgba(0,0,0,.45); padding: 16px; }
.rbx-announce-card{ width: min(420px, 100%); background: #fff; color: #111; border-radius: 8px; overflow: hidden; box-shadow: 0 14px 40px rgba(0,0,0,.5); font-family: Arial, Helvetica, sans-serif; }
.rbx-announce-head{ background: linear-gradient(#3b3f44, #2b2e32); color: #fff; font: 800 16px Arial, Helvetica, sans-serif; padding: 11px 16px; text-align: center; letter-spacing: .02em; }
.rbx-announce-body{ padding: 18px 20px 6px; font-size: 16px; line-height: 1.4; }
.rbx-announce-body p{ margin: 0 0 6px; white-space: pre-wrap; overflow-wrap: anywhere; }
.rbx-announce-body small{ color: #666; font-size: 12px; }
.rbx-announce-foot{ display: flex; justify-content: center; padding: 12px 16px 16px; }
.rbx-announce-ok{ min-width: 120px; font: 800 15px Arial, Helvetica, sans-serif; color: #fff; background: #02b757; border: 0; border-bottom: 3px solid #017a3c; border-radius: 6px; padding: 9px 18px; cursor: pointer; }
.rbx-announce-ok:active{ transform: translateY(1px); }
#rbx-playerlist .rbx-playerlist-rows{overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#949da9 #252a33;scrollbar-gutter:stable}
#rbx-playerlist .rbx-playerlist-rows::-webkit-scrollbar{display:block;width:8px;height:8px}
#rbx-playerlist .rbx-playerlist-rows::-webkit-scrollbar-track{background:#252a33;border-radius:5px}
#rbx-playerlist .rbx-playerlist-rows::-webkit-scrollbar-thumb{background:#949da9;border:2px solid #252a33;border-radius:5px}
#rbx-playerlist .rbx-playerlist-rows::-webkit-scrollbar-thumb:hover{background:#c1c9d4}
.rbx-local-chat-bubble.bubble-stack{display:flex;flex-direction:column;align-items:center;gap:6px;background:none;padding:0;max-width:240px;min-width:0;transform:translate(-50%,-110%)}
.rbx-local-chat-bubble.bubble-stack[hidden]{display:none}
